    /**
     * Get inventory summary for dashboard
     */
    public InventorySummaryDTO getInventorySummary() {
        InventorySummaryDTO summary = new InventorySummaryDTO();
        
        List<InventoryItem> allItems = inventoryItemRepository.findAll();
        
        // Total items
        summary.setTotalItems(allItems.size());
        
        // Category counts
        summary.setDyesCount((int) allItems.stream()
                .filter(item -> item.getCategory() != null && item.getCategory().getName().contains("Dye"))
                .count());
        
        summary.setChemicalsCount((int) allItems.stream()
                .filter(item -> item.getCategory() != null && item.getCategory().getName().contains("Chemical"))
                .count());
        
        summary.setSolventsCount((int) allItems.stream()
                .filter(item -> item.getCategory() != null && item.getCategory().getName().contains("Solvent"))
                .count());
        
        // Total solvents on hand (in liters)
        BigDecimal totalSolvents = allItems.stream()
                .filter(item -> item.getCategory() != null && 
                        item.getCategory().getName().contains("Solvent") && 
                        "L".equalsIgnoreCase(item.getUnitOfMeasure()))
                .map(InventoryItem::getCurrentQuantity)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        summary.setTotalSolventsOnHand(totalSolvents);
        summary.setSolventsGrowthPercent(new BigDecimal("12.0")); // Mock growth percentage
        
        // Low stock items count
        summary.setLowStockItemsCount((int) allItems.stream()
                .filter(item -> "Low Stock".equals(item.getStockStatus()) || 
                               "Out of Stock".equals(item.getStockStatus()))
                .count());
        
        // Total inventory value
        BigDecimal totalValue = allItems.stream()
                .map(InventoryItem::getTotalValue)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        summary.setTotalInventoryValue(totalValue);
        
        // Last update cycle
        summary.setLastUpdateCycle("24h");
        
        // Storage capacity (mock calculation)
        summary.setStorageCapacityUsedPercent(new BigDecimal("72.0"));
        
        return summary;
    }
    
