    /**
     * Get inventory item detail by ID
     */
    public InventoryItemDetailDTO getInventoryItemDetail(Long id) {
        InventoryItem item = inventoryItemRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Inventory item not found with id: " + id));
        
        InventoryItemDetailDTO detailDTO = convertToDetailDTO(item);
        
        // Get recent transactions (last 10)
        List<InventoryTransaction> transactions = transactionRepository.findTop10ByInventoryItemIdOrderByTransactionDateDesc(id);
        detailDTO.setRecentTransactions(transactions.stream()
                .map(this::convertTransactionToDTO)
                .collect(Collectors.toList()));
        
        return detailDTO;
    }
    
    /**
     * Create new inventory item
     */
    public InventoryItemDetailDTO createInventoryItem(InventoryItemCreateDTO createDTO) {
        // Generate item code
        String itemCode = generateItemCode(createDTO.getType());
        
        InventoryItem item = new InventoryItem();
        item.setItemCode(itemCode);
        item.setName(createDTO.getItemName());
        item.setDescription(createDTO.getDescription());
        item.setUnitOfMeasure(createDTO.getUnit());
        item.setCurrentQuantity(createDTO.getOpeningStock());
        item.setUnitCost(createDTO.getCostPerUnit());
        item.setMinimumQuantity(createDTO.getLowStockThreshold());
        item.setReorderPoint(createDTO.getLowStockThreshold());
        item.setLowStockAlertsEnabled(createDTO.getLowStockAlertsEnabled());
        item.setLocation(createDTO.getLocation());
        item.setWeight(createDTO.getWeight());
        item.setWidth(createDTO.getWidth());
        item.setSupplier(createDTO.getSupplier());
        item.setIsActive(true);
        
        // Find or create category based on type
        InventoryCategory category = categoryRepository.findByName(createDTO.getType())
                .orElseGet(() -> {
                    InventoryCategory newCategory = new InventoryCategory();
                    newCategory.setName(createDTO.getType());
                    newCategory.setDescription(createDTO.getType() + " category");
                    newCategory.setIsActive(true);
                    return categoryRepository.save(newCategory);
                });
        item.setCategory(category);
        
        InventoryItem savedItem = inventoryItemRepository.save(item);
        
        // Create initial transaction for opening stock
        if (createDTO.getOpeningStock().compareTo(BigDecimal.ZERO) > 0) {
            createTransaction(savedItem, "ADJUSTMENT", createDTO.getOpeningStock(),
                    "Opening Stock", "Initial inventory", "STOCK_IN", "OPENING_STOCK", null, LocalDate.now());
        }
        
        return convertToDetailDTO(savedItem);
    }
    
    /**
     * Update inventory item
     */
    public InventoryItemDetailDTO updateInventoryItem(Long id, InventoryItemCreateDTO updateDTO) {
        InventoryItem item = inventoryItemRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Inventory item not found with id: " + id));
        
        item.setName(updateDTO.getItemName());
        item.setDescription(updateDTO.getDescription());
        item.setUnitOfMeasure(updateDTO.getUnit());
        item.setUnitCost(updateDTO.getCostPerUnit());
        item.setMinimumQuantity(updateDTO.getLowStockThreshold());
        item.setReorderPoint(updateDTO.getLowStockThreshold());
        item.setLowStockAlertsEnabled(updateDTO.getLowStockAlertsEnabled());
        item.setLocation(updateDTO.getLocation());
        item.setWeight(updateDTO.getWeight());
        item.setWidth(updateDTO.getWidth());
        item.setSupplier(updateDTO.getSupplier());
        
        // Update category if type changed
        if (updateDTO.getType() != null) {
            InventoryCategory category = categoryRepository.findByName(updateDTO.getType())
                    .orElseGet(() -> {
                        InventoryCategory newCategory = new InventoryCategory();
                        newCategory.setName(updateDTO.getType());
                        newCategory.setDescription(updateDTO.getType() + " category");
                        newCategory.setIsActive(true);
                        return categoryRepository.save(newCategory);
                    });
            item.setCategory(category);
        }
        
        InventoryItem updatedItem = inventoryItemRepository.save(item);
        return convertToDetailDTO(updatedItem);
    }
    

    /**
     * Adjust stock (Stock In / Stock Out)
     */
    public InventoryItemDetailDTO adjustStock(StockAdjustmentDTO adjustmentDTO) {
        InventoryItem item = inventoryItemRepository.findById(adjustmentDTO.getInventoryItemId())
                .orElseThrow(() -> new RuntimeException("Inventory item not found"));

        BigDecimal requestedQuantity = adjustmentDTO.getQuantity();
        BigDecimal movementQuantity = requestedQuantity.abs();
        if (movementQuantity.compareTo(BigDecimal.ZERO) == 0) {
            throw new RuntimeException("Quantity must be greater than zero");
        }

        String movementType = adjustmentDTO.getMovementType() == null
                ? ""
                : adjustmentDTO.getMovementType().trim().toUpperCase();

        BigDecimal transactionQuantity;

        // Movement type controls stock direction regardless of request quantity sign.
        if ("STOCK_IN".equals(movementType)) {
            item.setCurrentQuantity(item.getCurrentQuantity().add(movementQuantity));
            transactionQuantity = movementQuantity;
        } else if ("STOCK_OUT".equals(movementType)) {
            BigDecimal newQuantity = item.getCurrentQuantity().subtract(movementQuantity);
            if (newQuantity.compareTo(BigDecimal.ZERO) < 0) {
                throw new RuntimeException("Insufficient stock. Current: " + item.getCurrentQuantity() + 
                        ", Requested: " + movementQuantity);
            }
            item.setCurrentQuantity(newQuantity);
            transactionQuantity = movementQuantity.negate();
        } else {
            throw new RuntimeException("Invalid movement type. Use STOCK_IN or STOCK_OUT");
        }
        
        InventoryItem savedItem = inventoryItemRepository.save(item);
        
        // Create transaction
        String transactionType = mapReasonToTransactionType(adjustmentDTO.getReason());
        createTransaction(savedItem, transactionType, transactionQuantity,
                adjustmentDTO.getReason(), adjustmentDTO.getNotes(),
                movementType, adjustmentDTO.getLinkedOrderId(),
                adjustmentDTO.getReferenceId(), adjustmentDTO.getEffectiveDate());
        
        return convertToDetailDTO(savedItem);
    }
    
    /**
     * Get inventory transactions for an item
     */
    public List<InventoryTransactionDTO> getInventoryTransactions(Long inventoryItemId) {
        List<InventoryTransaction> transactions = transactionRepository
                .findByInventoryItemIdOrderByTransactionDateDesc(inventoryItemId);
        
        return transactions.stream()
                .map(this::convertTransactionToDTO)
                .collect(Collectors.toList());
    }
    
