    private void createTransaction(InventoryItem item, String transactionType, BigDecimal quantity,
                                    String reason, String notes, String referenceType, String referenceNumber,
                                    Long referenceId, LocalDate transactionDate) {
        InventoryTransaction transaction = new InventoryTransaction();
        transaction.setInventoryItem(item);
        transaction.setTransactionType(transactionType);
        transaction.setQuantity(quantity);
        transaction.setUnitCost(item.getUnitCost());
        transaction.setTotalCost(quantity.multiply(item.getUnitCost()));
        transaction.setBalanceAfter(item.getCurrentQuantity());
        transaction.setTransactionDate(transactionDate != null ? transactionDate : LocalDate.now());
        transaction.setNotes(notes != null ? notes : reason);
        transaction.setReferenceType(referenceType);
        transaction.setReferenceNumber(referenceNumber);
        transaction.setReferenceId(referenceId);
        
        transactionRepository.save(transaction);
    }
    
    private String generateItemCode(String type) {
        String prefix;
        switch (type.toLowerCase()) {
            case "dye":
            case "dyes":
                prefix = "DYE";
                break;
            case "chemical":
            case "chemicals":
                prefix = "CHM";
                break;
            case "solvent":
            case "solvents":
                prefix = "SLV";
                break;
            case "auxiliary":
            case "auxiliaries":
                prefix = "AUX";
                break;
            case "raw material":
            case "raw materials":
                prefix = "RAW";
                break;
            default:
                prefix = "INV";
        }
        
        // Generate random 3-letter code + 3-digit number
        String randomCode = UUID.randomUUID().toString().substring(0, 3).toUpperCase();
        int randomNumber = (int) (Math.random() * 900) + 100;
        
        return prefix + "-" + randomCode + "-" + randomNumber;
    }
    
    private String mapReasonToTransactionType(String reason) {
        switch (reason.toLowerCase()) {
            case "purchase received":
            case "purchase order":
                return "PURCHASE";
            case "production usage":
            case "sample production":
                return "USAGE";
            case "customer return":
                return "RETURN";
            case "damage / wastage":
            case "damaged goods":
                return "ADJUSTMENT";
            case "inventory audit":
            case "manual adjustment":
                return "ADJUSTMENT";
            default:
                return "ADJUSTMENT";
        }
    }

    // ::: Code Generated by Copilot [b4f0548d-f80c-4d6f-9f53-f65fb6616845]. This comment will be removed automatically after the file is saved :::
    private String normalizeBlank(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
